package com.sabz.companion;
/** Deterministic habit feedback; intentionally independent of Android for testing. */
public final class NightReview {
 public static final class Data { public boolean complete,coverage,unknown;public double calories,protein,fiber,water,activity,sitting,longest;public double calorieGoal=2000,proteinGoal=56,fiberGoal=28,waterGoal=1600,activityGoal=22,sittingLimit=60; }
 private static double cap(double value,double goal){return Math.min(1,Math.max(0,value)/goal);}
 public static int score(Data d){return (int)Math.round(15*Math.max(0,1-Math.abs(d.calories-d.calorieGoal)/d.calorieGoal)+15*cap(d.protein,d.proteinGoal)+25*cap(d.fiber,d.fiberGoal)+20*cap(d.water,d.waterGoal)+15*cap(d.activity,d.activityGoal)+10*(d.sitting==0?1:Math.min(1,d.sittingLimit/Math.max(d.sittingLimit,d.longest))));}
 public static String message(Data d,boolean fa){if(!d.complete||!d.coverage)return fa?"اطلاعات امروز هنوز کامل نشده است. ثبت‌ها را مرور کن و اگر همه را وارد کرده‌ای، روز را کامل اعلام کن تا جمع‌بندی دقیق‌تری داشته باشیم.":"Today's record is not complete yet. Review your entries and mark the day complete once everything is logged.";if(d.unknown)return fa?"بخشی از ارزش غذایی خوراکی‌ها نامشخص است؛ امتیاز امروز قابل محاسبه نیست. اطلاعات خوراکی‌های سفارشی را کامل کن.":"Some food nutrition is unknown, so today's score is unavailable. Complete the nutrition information for custom foods.";int score=score(d);String intro=fa?(score>=75?"امروز خوب پیش رفتی 🍏":"فردا با چند قدم کوچک بهتر پیش می‌رویم 🍏"):(score>=75?"You made good progress today 🍏":"A few small steps for tomorrow 🍏");StringBuilder tips=new StringBuilder();int count=0;
 if(d.water<d.waterGoal*.9){tips.append(fa?"فردا آب را در طول روز منظم‌تر بنوش تا به هدف انتخابی نزدیک شوی.":"Tomorrow, spread water through the day toward your chosen target.");count++;}
 if(d.activity<d.activityGoal*.9&&count<2){if(count>0)tips.append(" ");tips.append(fa?"فردا زمانی برای پیاده‌روی یا فعالیت متناسب با توانت بگذار.":"Plan some walking or activity that suits your ability tomorrow.");count++;}
 if(d.longest>d.sittingLimit&&count<2){if(count>0)tips.append(" ");tips.append(fa?"فردا بین نوبت‌های نشستن زودتر بلند شو و کمی حرکت کن.":"Tomorrow, break up long sitting periods with a little movement.");count++;}
 if(d.fiber<d.fiberGoal*.9&&count<2){if(count>0)tips.append(" ");tips.append(fa?"فردا خوراکی‌های فیبردار متناسب با تحملت انتخاب کن؛ افزایش فیبر تدریجی باشد.":"Choose fiber-rich foods you tolerate tomorrow; increase fiber gradually.");count++;}
 if((d.calories<d.calorieGoal*.9||d.calories>d.calorieGoal*1.1)&&count<2){if(count>0)tips.append(" ");tips.append(fa?"فردا وعده‌ها را با هدف کالری انتخابی هماهنگ‌تر کن.":"Tomorrow, align meals more closely with your chosen calorie target.");count++;}
 if(d.protein<d.proteinGoal*.9&&count<2){if(count>0)tips.append(" ");tips.append(fa?"فردا منابع پروتئین را متناسب با هدفت در وعده‌ها بگنجان.":"Include protein sources that fit your chosen target tomorrow.");count++;}
 if(count==0)tips.append(fa?"همین عادت‌های منظم را فردا ادامه بده.":"Keep up these consistent habits tomorrow.");return intro+" · "+(fa?"امتیاز عادت‌ها: ":"Habit score: ")+score+"/100. "+tips; }
}
